Okay so I'm pretty happy with the public API of this.... There's a LOT of magic happening to abstract away the `onSubmit` requirement though. The pattern is the same one Remix source code uses to implement `fetcher.Form`.

1) Validators
```ts
export const bookmarkValidators: FormValidators<BookmarkFormValues> = {
  title: {
    required: true,
    maxLength: { value: 100, message: "Title must be less than 100 characters" },
  },
  url: {
    required: "Url is required",
    minLength: 7,
  },
};

```

2) Form Component
```tsx
interface BookmarkFormProps {
  initial?: BookmarkFormValues;
}

export function BookmarkForm({ initial }: BookmarkFormProps) {
  let form = useValidatedForm(initial);

  return (
    <form.Form method="post" style={{ maxWidth: "500px" }}>
        <input name="id" type="hidden" value={initial?.id}></input>
        <InputField
          error={form.errors.title}
          label="Title"
          {...form.register("title", { ...bookmarkValidators.title })}
          defaultValue={initial?.title || ""}
        />
        <InputField
          error={form.errors.url}
          label="URL"]
          {...form.register("url", { ...bookmarkValidators.url })}
          required
          defaultValue={initial?.url || ""}
        />
        <Button>Submit</Button>
    </form.Form>
  );
}
```

3) Action Function
```ts
export const action = ({ request }) => {
  const formData = await request.formData();
  let [errors, hasErrors] = await validate(formData, bookmarkValidators);
  if (hasErrors) {
    return {
      errors,
    };
  }

  const bookmark = await bookmarkService.save(Object.fromEntries(formData) as any);
  return redirect(`/bookmarks/${bookmark.id}`);
};
```
